 "content": "from collections import Counter


def transform(grid):
    """Extend matching-color markers along rows and columns with color 2."""
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    height, width = len(out), len(out[0])

    changed = True
    while changed:
        changed = False
        # A row or column's matching endpoints bridge only background cells;
        # other colored markers remain untouched. Iterate because bridges of
        # color 2 can themselves connect further matching 2s.
        for r in range(height):
            positions = {}
            for c, value in enumerate(out[r]):
                if value != background:
                    positions.setdefault(value, []).append(c)
            for cols in positions.values():
                for left, right in zip(cols, cols[1:]):
                    for c in range(left + 1, right):
                        if out[r][c] == background:
                            out[r][c] = 2
                            changed = True

        for c in range(width):
            positions = {}
            for r in range(height):
                value = out[r][c]
                if value != background:
                    positions.setdefault(value, []).append(r)
            for rows in positions.values():
                for top, bottom in zip(rows, rows[1:]):
                    for r in range(top + 1, bottom):
                        if out[r][c] == background:
                            out[r][c] = 2
                            changed = True
    return out


if __name__ == "__main__":
    test = [
        [8,8,1,1,1,1,1,1,8],
