def transform(grid):
    """Bridge short gaps and complete longer multi-marker horizontal/vertical runs."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Lines with three or more input marks are structural runs; their spans
    # can extend to intersecting newly completed runs. Two-mark lines repair
    # only a short local gap (up to five cells between marks).
    active_rows, active_cols = [], []
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value != background]
        if len(cols) >= 3:
            active_rows.append(r)
        elif len(cols) == 2 and cols[1] - cols[0] <= 5:
            for c in range(cols[0] + 1, cols[1]):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != background]
        if len(rows) >= 3:
            active_cols.append(c)
        elif len(rows) == 2 and rows[1] - rows[0] <= 5:
            for r in range(rows[0] + 1, rows[1]):
                if grid[r][c] == background:
                    out[r][c] = 2

    while True:
        additions = set()
        for r in active_rows:
            marked = [c for c, value in enumerate(out[r]) if value != background]
            if marked:
                additions.update((r, c) for c in range(marked[0], marked[-1] + 1)
