    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Horizontal strokes with multiple anchors have their interior gaps filled.
    for r in range(h):
        marks = [c for c, v in enumerate(grid[r]) if v != background]
        if len(marks) >= 3:
            for c in range(marks[0] + 1, marks[-1]):
                if grid[r][c] == background:
                    out[r][c] = 2
        elif len(marks) == 2:
            # A two-anchor row can be a terminal crossbar joining two vertical
            # strokes; fill it only if both strokes end at this row.
            c1, c2 = marks
            below1 = any(grid[rr][c1] != background for rr in range(r + 1, h))
            below2 = any(grid[rr][c2] != background for rr in range(r + 1, h))
            above1 = any(grid[rr][c1] != background for rr in range(r))
            above2 = any(grid[rr][c2] != background for rr in range(r))
            if above1 and above2 and not below1 and not below2:
                for c in range(c1 + 1, c2):
                    if grid[r][c] == background:
                        out[r][c] = 2

    # Vertical strokes: gaps between repeated aligned anchors.
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != background]
