    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Fill lines supported by at least three markers. Iterate so crossings
    # that become supported by vertical bridges are filled as well.
    while True:
        additions = set()
        for r in range(h):
            marks = [c for c, value in enumerate(out[r]) if value != background]
            if len(marks) >= 3:
