def transform(grid):
    """Fill gaps between consecutive same-color markers in rows and columns."""
    height, width = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    output = [row[:] for row in grid]

    # Use original markers as endpoints. Fill only background cells between
    # consecutive occurrences of the same non-background color.
    for r in range(height):
        positions_by_color = {}
        for c, value in enumerate(grid[r]):
            if value != background:
                positions_by_color.setdefault(value, []).append(c)
        for positions in positions_by_color.values():
            for left, right in zip(positions, positions[1:]):
                for c in range(left + 1, right):
                    if grid[r][c] == background:
                        output[r][c] = 2

    for c in range(width):
        positions_by_color = {}
        for r in range(height):
            value = grid[r][c]
            if value != background:
                positions_by_color.setdefault(value, []).append(r)
        for positions in positions_by_color.values():
            for top, bottom in zip(positions, positions[1:]):
