def transform(grid):
    """Repair broken vertical strokes and anchored horizontal bars."""
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Verticals: repeated aligned markers indicate strokes; fill all gaps
    # between their top and bottom markers (including two-marker strokes).
    for c in range(w):
        anchors = [r for r in range(h) if grid[r][c] != background]
        if len(anchors) >= 2:
            for r in range(anchors[0] + 1, anchors[-1]):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Horizontal bars have a consecutive run of markers, or are the terminal
    # crossbar connecting two vertical strokes that both end on this row.
    for r in range(h):
        anchors = [c for c, value in enumerate(grid[r]) if value != background]
        has_run = any(b == a + 1 for a, b in zip(anchors, anchors[1:]))
        terminal_bar = False
        if len(anchors) == 2:
            left, right = anchors
            left_rows = [rr for rr in range(h) if grid[rr][left] != background]
            right_rows = [rr for rr in range(h) if grid[rr][right] != background]
            terminal_bar = (len(left_rows) >= 3 and len(right_rows) >= 3
                            and left_rows[-1] == r and right_rows[-1] == r)
        if has_run or terminal_bar:
            for c in range(anchors[0] + 1, anchors[-1]):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out


