def _fill_line(values, original, orientation, index, background, additions):
    """Return gap coordinates on a line containing an adjacent marker run."""
    marks = [p for p, value in enumerate(values) if value != background]
    if len(marks) < 3:
        return
    # At least two directly touching markers establish a real stroke, rather
    # than three unrelated isolated points that happen to share a line.
    has_run = any(b == a + 1 for a, b in zip(marks, marks[1:]))
    if not has_run:
        return
    for p in range(marks[0] + 1, marks[-1]):
        if values[p] == background:
            additions.add((index, p) if orientation == "row" else (p, index))


def transform(grid):
    """Bridge gaps between marker clusters on established horizontal/vertical strokes."""
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Iterate to let a completed stroke connect at a crossing, while never
    # overwriting original marker colors.
    while True:
        additions = set()
        for r in range(h):
            _fill_line(out[r], grid[r], "row", r, background, additions)
        for c in range(w):
            values = [out[r][c] for r in range(h)]
            _fill_line(values, None, "col", c, background, additions)
        if not additions:
            break
        for r, c in additions:
            out[r][c] = 2
    return out


